# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İLK VAHİY (610), İLK MÜSLÜMANLAR VE DAVETİN AŞAMALARI</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. İLK VAHİY VE İLK MÜSLÜMANLAR (SÂBİKÛN)</text>\n  <text x="42" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">• Mekân ve Zaman: Nur Dağı Hira Mağarası, 610 Ramazan</text>\n  <text x="42" y="116" font-size="11" font-weight="bold" fill="#1e3a8a">• İlk İnen Ayetler: Alak Suresi 1-5 ("Yaratan Rabbinin</text>\n  <text x="50" y="132" font-size="11" font-weight="bold" fill="#1e3a8a">adıyla oku!") · Ardından Fetretü\'l-Vahiy ve Müddessir</text>\n  <text x="42" y="156" font-size="11" font-weight="bold" fill="#1d4ed8">• İlk Müslümanlar (es-Sâbikûne\'l-Evvelûn):</text>\n  <text x="50" y="174" font-size="10.5" fill="#1e3a8a">- İlk Kadın: Hz. Hatice · İlk Çocuk/Genç: Hz. Ali</text>\n  <text x="50" y="192" font-size="10.5" fill="#1e3a8a">- İlk Azatlı Köle: Hz. Zeyd bin Hârise</text>\n  <text x="50" y="210" font-size="10.5" fill="#1e3a8a">- İlk Hür Erkek (Yakın Dost): Hz. Ebû Bekir</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">2. GİZLİ DAVET (3 YIL) VE AÇIK DAVET</text>\n  <text x="377" y="94" font-size="11" font-weight="bold" fill="#14532d">• Gizli (Bireysel) Davet Dönemi (610 - 613):</text>\n  <text x="385" y="112" font-size="10.5" fill="#166534">Müddessir 1-7 ile başladı, 3 yıl sürdü. Merkez olarak</text>\n  <text x="385" y="128" font-size="10.5" font-weight="bold" fill="#14532d">Dârü\'l-Erkam (Erkam bin Ebi\'l-Erkam\'ın evi) seçildi.</text>\n  <text x="377" y="154" font-size="11" font-weight="bold" fill="#14532d">• Açık Davet Dönemi (613 - 622):</text>\n  <text x="385" y="172" font-size="10.5" fill="#166534">1) Şuarâ 214 ("En yakın akrabalarını uyar!") →</text>\n  <text x="393" y="188" font-size="10.5" font-weight="bold" fill="#14532d">Safa Tepesi konuşması ve yakın akrabaya davet.</text>\n  <text x="385" y="206" font-size="10.5" fill="#166534">2) Hicr 94 ("Emrolunduğun şeyi açıkça ortaya koy!") →</text>\n  <text x="393" y="222" font-size="10.5" font-weight="bold" fill="#14532d">Bütün Mekke halkına ve kabilelere genel davet.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MEKKELİ MÜŞRİKLERİN İSLAM DAVETİNE TEPKİLERİ VE NEDENLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">NEDEN KARŞI ÇIKTILAR? (TEMEL SEBEPLER)</text>\n  <text x="42" y="95" font-size="11" fill="#713f12">• Putperestlik ve Kör Taklit: "Atalarımızın dinini</text>\n  <text x="50" y="111" font-size="11" fill="#713f12">bırakmayız" anlayışı ve tevhide direnç.</text>\n  <text x="42" y="135" font-size="11" fill="#713f12">• Siyasi ve Ekonomik Çıkar Kaygısı: Mekke\'deki</text>\n  <text x="50" y="151" font-size="11" fill="#713f12">liderlik, ticaret ve put gelirlerini kaybetme korkusu.</text>\n  <text x="42" y="175" font-size="11" fill="#713f12">• Toplumsal Eşitlik İlkesi: Köle ile efendiyi eşit</text>\n  <text x="50" y="191" font-size="11" fill="#713f12">tutan İslam ahlakını kibirlerine yedirememeleri.</text>\n  <text x="42" y="215" font-size="11" fill="#713f12">• Ahiret ve Hesap Korkusu: Zulüm ve haksızlıklar.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">UYGULADIKLARI BASKI YÖNTEMLERİ</text>\n  <text x="377" y="95" font-size="11" font-weight="bold" fill="#7f1d1d">1. Alay, İftira ve Karalama Kampanyası:</text>\n  <text x="385" y="111" font-size="10.5" fill="#991b1b">Şair, kâhin, sihirbaz, mecnun ve "eskilerin masalları"</text>\n  <text x="377" y="135" font-size="11" font-weight="bold" fill="#7f1d1d">2. Uzlaşma ve Dünyalık Teklifler (Ebû Talip Aracılığı):</text>\n  <text x="385" y="151" font-size="10.5" fill="#991b1b">Mal, mülk, başkanlık teklifi → "Güneş\'i sağ elime..."</text>\n  <text x="377" y="175" font-size="11" font-weight="bold" fill="#7f1d1d">3. Fiziksel İşkence ve Şehadetler:</text>\n  <text x="385" y="191" font-size="10.5" fill="#991b1b">Bilâl-i Habeşî, Habbâb; Ammâr ailesi (Hz. Sümeyye, Yâsir)</text>\n  <text x="377" y="215" font-size="11" font-weight="bold" fill="#7f1d1d">4. Sosyal ve Ekonomik Boykot (616-619, 3 Yıl)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HABEŞİSTAN HİCRETİ (615-616), BOYKOT VE HÜZÜN YILI (619)</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">HABEŞİSTAN HİCRETLERİ (615 ve 616)</text>\n  <text x="42" y="94" font-size="11" font-weight="bold" fill="#581c87">• Neden Habeşistan?</text>\n  <text x="50" y="110" font-size="10.5" fill="#4c1d95">Hz. Peygamber: "Orada yanında kimseye zulmedilmeyen</text>\n  <text x="50" y="125" font-size="10.5" fill="#4c1d95">adil bir hükümdar (Necaşi Ashame) vardır" buyurdu.</text>\n  <text x="42" y="149" font-size="11" font-weight="bold" fill="#581c87">• 1. Kafile (615): 11 erkek, 4 kadın (Hz. Osman ve</text>\n  <text x="50" y="164" font-size="10.5" fill="#4c1d95">Hz. Rukiyye dahil) · 2. Kafile (616): ~82 erkek, 18 kadın.</text>\n  <text x="42" y="188" font-size="11" font-weight="bold" fill="#581c87">• Sözcü: Hz. Cafer bin Ebû Talip (Meryem suresi tilaveti</text>\n  <text x="50" y="204" font-size="10.5" fill="#4c1d95">ile müşrik elçileri Amr bin Âs\'ın talebini boşa çıkardı).</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">BOYKOT YILLARI, HÜZÜN YILI VE TAİF</text>\n  <text x="377" y="94" font-size="11" font-weight="bold" fill="#7c2d12">• Hz. Hamza ve Hz. Ömer\'in Müslüman Oluşu (615-616):</text>\n  <text x="385" y="110" font-size="10.5" fill="#9a3412">Müslümanlara moral verdi, Kâbe\'de açıktan namaz kılındı.</text>\n  <text x="377" y="134" font-size="11" font-weight="bold" fill="#7c2d12">• Genel Boykot (616 - 619, Şi\'b-i Ebû Talip):</text>\n  <text x="385" y="150" font-size="10.5" fill="#9a3412">Haşimoğulları ile evlilik ve alışveriş 3 yıl yasaklandı.</text>\n  <text x="377" y="174" font-size="11" font-weight="bold" fill="#7c2d12">• Hüzün Yılı (Senetü\'l-Hüzün — 619):</text>\n  <text x="385" y="190" font-size="10.5" fill="#9a3412">Amcası Ebû Talip ve eşi Hz. Hatice peş peşe vefat etti.</text>\n  <text x="377" y="214" font-size="11" font-weight="bold" fill="#7c2d12">• Taif Yolculuğu (620) ve İsrâ-Miraç Mucizesi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
